[<Interface>]
type HookCallbacks =
    /// <summary>
    /// Called when a class is constructed that has the possibility to emit an asynchronous event.
    /// </summary>
    /// <param name="asyncId">A unique ID for the async resource</param>
    /// <param name="type">The type of the async resource</param>
    /// <param name="triggerAsyncId">The unique ID of the async resource in whose execution context this async resource was created</param>
    /// <param name="resource">Reference to the resource representing the async operation, needs to be released during destroy</param>
    abstract init: Init2 option with get, set
    /// <summary>
    /// When an asynchronous operation is initiated or completes a callback is called to notify the user.
    /// The before callback is called just before said callback is executed.
    /// </summary>
    /// <param name="asyncId">the unique identifier assigned to the resource about to execute the callback.</param>
    abstract before: (float -> unit) option with get, set
    /// <summary>
    /// Called immediately after the callback specified in <c>before</c> is completed.
    /// <br /><br />
    /// If an uncaught exception occurs during execution of the callback, then <c>after</c> will run after the <c>'uncaughtException'</c> event is emitted or a <c>domain</c>'s handler runs.
    /// </summary>
    /// <param name="asyncId">the unique identifier assigned to the resource which has executed the callback.</param>
    abstract after: (float -> unit) option with get, set
    /// <summary>
    /// Called when a promise has resolve() called. This may not be in the same execution id
    /// as the promise itself.
    /// </summary>
    /// <param name="asyncId">the unique id for the promise that was resolve()d.</param>
    abstract promiseResolve: (float -> unit) option with get, set
    /// <summary>
    /// Called after the resource corresponding to asyncId is destroyed
    /// </summary>
    /// <param name="asyncId">a unique ID for the async resource</param>
    abstract destroy: (float -> unit) option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (?init: Init2, ?before: (float -> unit), ?after: (float -> unit), ?promiseResolve: (float -> unit), ?destroy: (float -> unit)) : HookCallbacks = jsNative

type Init2 = delegate of asyncId: float * ``type``: string * triggerAsyncId: float * resource: obj -> unit

[<Interface>]
type AsyncHook =
    /// <summary>
    /// Enable the callbacks for a given AsyncHook instance. If no callbacks are provided enabling is a noop.
    /// </summary>
    abstract enable: unit -> AsyncHook
    /// <summary>
    /// Disable the callbacks for a given AsyncHook instance from the global pool of AsyncHook callbacks to be executed. Once a hook has been disabled it will not be called again until enabled.
    /// </summary>
    abstract disable: unit -> AsyncHook
