        | [<CompiledName("finish")>] Finish

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type Pipe =
        | [<CompiledName("pipe")>] Pipe

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type Unpipe =
        | [<CompiledName("unpipe")>] Unpipe

type WritableStream3 =
    inherit EventEmitter2<unit[]>
    abstract writable: bool with get, set
    abstract write: buffer: U2<string, JS.Uint8Array> * ?cb: (exn option -> unit) -> bool
    abstract write: str: string * ?encoding: BufferEncoding * ?cb: (exn option -> unit) -> bool
    abstract ``end``: ?cb: (unit -> unit) -> WritableStream3
    abstract ``end``: data: U2<string, JS.Uint8Array> * ?cb: (unit -> unit) -> WritableStream3
    abstract ``end``: str: string * ?encoding: BufferEncoding * ?cb: (unit -> unit) -> WritableStream3
    /// <summary>
    /// Alias for <c>emitter.on(eventName, listener)</c>.
    /// </summary>
    /// <remarks>@since v0.1.26</remarks>
    abstract addListener: eventName: obj * listener: (obj[] -> unit) -> WritableStream3
    /// <summary>
    /// Adds the <c>listener</c> function to the end of the listeners array for the event
    /// named <c>eventName</c>. No checks are made to see if the <c>listener</c> has already
    /// been added. Multiple calls passing the same combination of <c>eventName</c> and
    /// <c>listener</c> will result in the <c>listener</c> being added, and called, multiple times.
    /// <code lang="js">
    /// server.on('connection', (stream) =&gt; {
    ///   console.log('someone connected!');
    /// });
    /// </code>
    /// <br /><br />
    /// Returns a reference to the <c>EventEmitter</c>, so that calls can be chained.
    /// <br /><br />
    /// By default, event listeners are invoked in the order they are added. The <c>emitter.prependListener()</c> method can be used as an alternative to add the
    /// event listener to the beginning of the listeners array.
    /// <code lang="js">
    /// import { EventEmitter } from 'node:events';
    /// const myEE = new EventEmitter();
    /// myEE.on('foo', () =&gt; console.log('a'));
    /// myEE.prependListener('foo', () =&gt; console.log('b'));
    /// myEE.emit('foo');
    /// // Prints:
    /// //   b
    /// //   a
    /// </code>
    /// </summary>
    /// <remarks>@since v0.1.101</remarks>
    /// <param name="eventName">The name of the event.</param>
    /// <param name="listener">The callback function</param>
    abstract on: eventName: obj * listener: (obj[] -> unit) -> WritableStream3
    /// <summary>
    /// Adds a <b>one-time</b> <c>listener</c> function for the event named <c>eventName</c>. The
    /// next time <c>eventName</c> is triggered, this listener is removed and then invoked.
    /// <code lang="js">
    /// server.once('connection', (stream) =&gt; {
    ///   console.log('Ah, we have our first user!');
    /// });
    /// </code>
    /// <br /><br />
    /// Returns a reference to the <c>EventEmitter</c>, so that calls can be chained.
    /// <br /><br />
    /// By default, event listeners are invoked in the order they are added. The <c>emitter.prependOnceListener()</c> method can be used as an alternative to add the
    /// event listener to the beginning of the listeners array.
    /// <code lang="js">
    /// import { EventEmitter } from 'node:events';
    /// const myEE = new EventEmitter();
    /// myEE.once('foo', () =&gt; console.log('a'));
    /// myEE.prependOnceListener('foo', () =&gt; console.log('b'));
    /// myEE.emit('foo');
    /// // Prints:
    /// //   b
    /// //   a
    /// </code>
    /// </summary>
    /// <remarks>@since v0.3.0</remarks>
    /// <param name="eventName">The name of the event.</param>
    /// <param name="listener">The callback function</param>
    abstract once: eventName: obj * listener: (obj[] -> unit) -> WritableStream3
    /// <summary>
    /// Removes the specified <c>listener</c> from the listener array for the event named <c>eventName</c>.
    /// <code lang="js">
    /// const callback = (stream) =&gt; {
    ///   console.log('someone connected!');
    /// };
    /// server.on('connection', callback);
    /// // ...
    /// server.removeListener('connection', callback);
    /// </code>
    /// <br /><br />
    /// <c>removeListener()</c> will remove, at most, one instance of a listener from the
    /// listener array. If any single listener has been added multiple times to the
    /// listener array for the specified <c>eventName</c>, then <c>removeListener()</c> must be
    /// called multiple times to remove each instance.
    /// <br /><br />
    /// Once an event is emitted, all listeners attached to it at the
    /// time of emitting are called in order. This implies that any <c>removeListener()</c> or <c>removeAllListeners()</c> calls _after_ emitting and _before_ the last listener finishes execution
    /// will not remove them from<c>emit()</c> in progress. Subsequent events behave as expected.
    /// <code lang="js">
    /// import { EventEmitter } from 'node:events';
    /// class MyEmitter extends EventEmitter {}
    /// const myEmitter = new MyEmitter();
    ///
    /// const callbackA = () =&gt; {
    ///   console.log('A');
    ///   myEmitter.removeListener('event', callbackB);
    /// };
    ///
    /// const callbackB = () =&gt; {
    ///   console.log('B');
    /// };
    ///
    /// myEmitter.on('event', callbackA);
    ///
    /// myEmitter.on('event', callbackB);
    ///
    /// // callbackA removes listener callbackB but it will still be called.
    /// // Internal listener array at time of emit [callbackA, callbackB]
    /// myEmitter.emit('event');
    /// // Prints:
    /// //   A
    /// //   B
    ///
    /// // callbackB is now removed.
    /// // Internal listener array [callbackA]
    /// myEmitter.emit('event');
    /// // Prints:
    /// //   A
    /// </code>
    /// <br /><br />
    /// Because listeners are managed using an internal array, calling this will
    /// change the position indices of any listener registered _after_ the listener
    /// being removed. This will not impact the order in which listeners are called,
    /// but it means that any copies of the listener array as returned by
    /// the <c>emitter.listeners()</c> method will need to be recreated.
    /// <br /><br />
    /// When a single function has been added as a handler multiple times for a single
    /// event (as in the example below), <c>removeListener()</c> will remove the most
    /// recently added instance. In the example the <c>once('ping')</c> listener is removed:
    /// <code lang="js">
    /// import { EventEmitter } from 'node:events';
    /// const ee = new EventEmitter();
    ///
    /// function pong() {
    ///   console.log('pong');
    /// }
    ///
    /// ee.on('ping', pong);
    /// ee.once('ping', pong);
    /// ee.removeListener('ping', pong);
    ///
    /// ee.emit('ping');
    /// ee.emit('ping');
    /// </code>
    /// <br /><br />
    /// Returns a reference to the <c>EventEmitter</c>, so that calls can be chained.
    /// </summary>
    /// <remarks>@since v0.1.26</remarks>
    abstract removeListener: eventName: obj * listener: (obj[] -> unit) -> WritableStream3
    /// <summary>
    /// Alias for <c>emitter.removeListener()</c>.
    /// </summary>
    /// <remarks>@since v10.0.0</remarks>
    abstract off: eventName: obj * listener: (obj[] -> unit) -> WritableStream3
    /// <summary>
    /// Removes all listeners, or those of the specified <c>eventName</c>.
    /// <br /><br />
    /// It is bad practice to remove listeners added elsewhere in the code,
    /// particularly when the <c>EventEmitter</c> instance was created by some other
    /// component or module (e.g. sockets or file streams).
    /// <br /><br />
    /// Returns a reference to the <c>EventEmitter</c>, so that calls can be chained.
    /// </summary>
    /// <remarks>@since v0.1.26</remarks>
    abstract removeAllListeners: ?eventName: obj -> WritableStream3
    /// <summary>
    /// By default <c>EventEmitter</c>s will print a warning if more than <c>10</c> listeners are
    /// added for a particular event. This is a useful default that helps finding
    /// memory leaks. The <c>emitter.setMaxListeners()</c> method allows the limit to be
    /// modified for this specific <c>EventEmitter</c> instance. The value can be set to <c>Infinity</c> (or <c>0</c>) to indicate an unlimited number of listeners.
    /// <br /><br />
    /// Returns a reference to the <c>EventEmitter</c>, so that calls can be chained.
    /// </summary>
    /// <remarks>@since v0.3.5</remarks>
    abstract setMaxListeners: n: float -> WritableStream3
    /// <summary>
    /// Returns a copy of the array of listeners for the event named <c>eventName</c>.
    /// <code lang="js">
    /// server.on('connection', (stream) =&gt; {
    ///   console.log('someone connected!');
    /// });
    /// console.log(util.inspect(server.listeners('connection')));
    /// // Prints: [ [Function] ]
    /// </code>
    /// </summary>
    /// <remarks>@since v0.1.26</remarks>
    abstract listeners: eventName: obj -> JS.Function[]
    /// <summary>
    /// Returns a copy of the array of listeners for the event named <c>eventName</c>,
    /// including any wrappers (such as those created by <c>.once()</c>).
    /// <code lang="js">
    /// import { EventEmitter } from 'node:events';
    /// const emitter = new EventEmitter();
    /// emitter.once('log', () =&gt; console.log('log once'));
    ///
    /// // Returns a new Array with a function `onceWrapper` which has a property
    /// // `listener` which contains the original listener bound above
    /// const listeners = emitter.rawListeners('log');
    /// const logFnWrapper = listeners[0];
    ///
    /// // Logs "log once" to the console and does not unbind the `once` event
    /// logFnWrapper.listener();
    ///
    /// // Logs "log once" to the console and removes the listener
    /// logFnWrapper();
    ///
    /// emitter.on('log', () =&gt; console.log('log persistently'));
    /// // Will return a new Array with a single function bound by `.on()` above
    /// const newListeners = emitter.rawListeners('log');
    ///
    /// // Logs "log persistently" twice
    /// newListeners[0]();
    /// emitter.emit('log');
    /// </code>
    /// </summary>
    /// <remarks>@since v9.4.0</remarks>
    abstract rawListeners: eventName: obj -> JS.Function[]
    /// <summary>
    /// Synchronously calls each of the listeners registered for the event named <c>eventName</c>, in the order they were registered, passing the supplied arguments
    /// to each.
    /// <br /><br />
    /// Returns <c>true</c> if the event had listeners, <c>false</c> otherwise.
    /// <code lang="js">
    /// import { EventEmitter } from 'node:events';
    /// const myEmitter = new EventEmitter();
    ///
    /// // First listener
    /// myEmitter.on('event', function firstListener() {
    ///   console.log('Helloooo! first listener');
    /// });
    /// // Second listener
    /// myEmitter.on('event', function secondListener(arg1, arg2) {
    ///   console.log(`event with parameters ${arg1}, ${arg2} in second listener`);
    /// });
    /// // Third listener
    /// myEmitter.on('event', function thirdListener(...args) {
    ///   const parameters = args.join(', ');
    ///   console.log(`event with parameters ${parameters} in third listener`);
    /// });
    ///
    /// console.log(myEmitter.listeners('event'));
    ///
    /// myEmitter.emit('event', 1, 2, 3, 4, 5);
    ///
    /// // Prints:
    /// // [
    /// //   [Function: firstListener],
    /// //   [Function: secondListener],
    /// //   [Function: thirdListener]
    /// // ]
    /// // Helloooo! first listener
    /// // event with parameters 1, 2 in second listener
    /// // event with parameters 1, 2, 3, 4, 5 in third listener
    /// </code>
    /// </summary>
    /// <remarks>@since v0.1.26</remarks>
    abstract emit: eventName: obj * [<ParamArray>] args: obj[] -> bool
    /// <summary>
    /// Returns the number of listeners listening for the event named <c>eventName</c>.
    /// If <c>listener</c> is provided, it will return how many times the listener is found
    /// in the list of the listeners of the event.
    /// </summary>
    /// <remarks>@since v3.2.0</remarks>
    /// <param name="eventName">The name of the event being listened for</param>
    /// <param name="listener">The event handler function</param>
    abstract listenerCount: eventName: obj * ?listener: JS.Function -> float
    /// <summary>
    /// Adds the <c>listener</c> function to the _beginning_ of the listeners array for the
    /// event named <c>eventName</c>. No checks are made to see if the <c>listener</c> has
    /// already been added. Multiple calls passing the same combination of <c>eventName</c>
    /// and <c>listener</c> will result in the <c>listener</c> being added, and called, multiple times.
    /// <code lang="js">
    /// server.prependListener('connection', (stream) =&gt; {
    ///   console.log('someone connected!');
    /// });
    /// </code>
    /// <br /><br />
    /// Returns a reference to the <c>EventEmitter</c>, so that calls can be chained.
    /// </summary>
    /// <remarks>@since v6.0.0</remarks>
    /// <param name="eventName">The name of the event.</param>
    /// <param name="listener">The callback function</param>
    abstract prependListener: eventName: obj * listener: (obj[] -> unit) -> WritableStream3
    /// <summary>
    /// Adds a <b>one-time</b><c>listener</c> function for the event named <c>eventName</c> to the _beginning_ of the listeners array. The next time <c>eventName</c> is triggered, this
    /// listener is removed, and then invoked.
    /// <code lang="js">
    /// server.prependOnceListener('connection', (stream) =&gt; {
    ///   console.log('Ah, we have our first user!');
    /// });
    /// </code>
    /// <br /><br />
    /// Returns a reference to the <c>EventEmitter</c>, so that calls can be chained.
    /// </summary>
    /// <remarks>@since v6.0.0</remarks>
    /// <param name="eventName">The name of the event.</param>
    /// <param name="listener">The callback function</param>
    abstract prependOnceListener: eventName: obj * listener: (obj[] -> unit) -> WritableStream3

type Writev = delegate of chunks: Writev.Chunks.Item[] * callback: (exn option -> unit) -> unit

module Writev =
    module Chunks =
        [<Interface>]
        type Item =
            abstract chunk: obj with get, set
            abstract encoding: BufferEncoding with get, set
            [<ParamObject; Emit("$0")>]
            static member Create (chunk: obj, encoding: BufferEncoding) : Item = jsNative

/// <summary>
/// Instances of the <c>ChildProcess</c> represent spawned child processes.
/// <br /><br />
/// Instances of <c>ChildProcess</c> are not intended to be created directly. Rather,
/// use the spawn, exec,execFile, or fork methods to create
/// instances of <c>ChildProcess</c>.
/// </summary>
/// <remarks>@since v2.2.0</remarks>
[<Interface>]
[<Import("ChildProcess", "child_process")>]
type ChildProcess =
    inherit EventEmitter<unit[]>
    /// <summary>
    /// A <c>Writable Stream</c> that represents the child process's <c>stdin</c>.
    /// <br /><br />
    /// If a child process waits to read all of its input, the child will not continue
    /// until this stream has been closed via <c>end()</c>.
    /// <br /><br />
    /// If the child was spawned with <c>stdio[0]</c> set to anything other than <c>'pipe'</c>,
    /// then this will be <c>null</c>.
    /// <br /><br />
    /// <c>subprocess.stdin</c> is an alias for <c>subprocess.stdio[0]</c>. Both properties will
    /// refer to the same value.
    /// <br /><br />
    /// The <c>subprocess.stdin</c> property can be <c>null</c> or <c>undefined</c> if the child process could not be successfully spawned.
    /// </summary>
    /// <remarks>@since v0.1.90</remarks>
    abstract stdin: Writable option with get, set
    /// <summary>
    /// A <c>Readable Stream</c> that represents the child process's <c>stdout</c>.
    /// <br /><br />
    /// If the child was spawned with <c>stdio[1]</c> set to anything other than <c>'pipe'</c>,
    /// then this will be <c>null</c>.
    /// <br /><br />
    /// <c>subprocess.stdout</c> is an alias for <c>subprocess.stdio[1]</c>. Both properties will
    /// refer to the same value.
    /// <code lang="js">
    /// import { spawn } from 'node:child_process';
    ///
    /// const subprocess = spawn('ls');
    ///
    /// subprocess.stdout.on('data', (data) =&gt; {
    ///   console.log(`Received chunk ${data}`);
    /// });
    /// </code>
    /// <br /><br />
    /// The <c>subprocess.stdout</c> property can be <c>null</c> or <c>undefined</c> if the child process could not be successfully spawned.
    /// </summary>
    /// <remarks>@since v0.1.90</remarks>
    abstract stdout: Readable option with get, set
    /// <summary>
    /// A <c>Readable Stream</c> that represents the child process's <c>stderr</c>.
    /// <br /><br />
    /// If the child was spawned with <c>stdio[2]</c> set to anything other than <c>'pipe'</c>,
    /// then this will be <c>null</c>.
    /// <br /><br />
    /// <c>subprocess.stderr</c> is an alias for <c>subprocess.stdio[2]</c>. Both properties will
    /// refer to the same value.
    /// <br /><br />
    /// The <c>subprocess.stderr</c> property can be <c>null</c> or <c>undefined</c> if the child process could not be successfully spawned.
    /// </summary>
    /// <remarks>@since v0.1.90</remarks>
    abstract stderr: Readable option with get, set
    /// <summary>
    /// The <c>subprocess.channel</c> property is a reference to the child's IPC channel. If
    /// no IPC channel exists, this property is <c>undefined</c>.
    /// </summary>
    /// <remarks>@since v7.1.0</remarks>
    abstract channel: Control option
    /// <summary>
    /// A sparse array of pipes to the child process, corresponding with positions in
    /// the <c>stdio</c> option passed to spawn that have been set
    /// to the value <c>'pipe'</c>. <c>subprocess.stdio[0]</c>, <c>subprocess.stdio[1]</c>, and <c>subprocess.stdio[2]</c> are also available as <c>subprocess.stdin</c>, <c>subprocess.stdout</c>, and <c>subprocess.stderr</c>,
    /// respectively.
    /// <br /><br />
    /// In the following example, only the child's fd <c>1</c> (stdout) is configured as a
    /// pipe, so only the parent's <c>subprocess.stdio[1]</c> is a stream, all other values
    /// in the array are <c>null</c>.
    /// <code lang="js">
    /// import assert from 'node:assert';
    /// import fs from 'node:fs';
    /// import child_process from 'node:child_process';
    ///
    /// const subprocess = child_process.spawn('ls', {
    ///   stdio: [
    ///     0, // Use parent's stdin for child.
    ///     'pipe', // Pipe child's stdout to parent.
    ///     fs.openSync('err.out', 'w'), // Direct child's stderr to a file.
    ///   ],
    /// });
    ///
    /// assert.strictEqual(subprocess.stdio[0], null);
    /// assert.strictEqual(subprocess.stdio[0], subprocess.stdin);
    ///
    /// assert(subprocess.stdout);
    /// assert.strictEqual(subprocess.stdio[1], subprocess.stdout);
    ///
    /// assert.strictEqual(subprocess.stdio[2], null);
    /// assert.strictEqual(subprocess.stdio[2], subprocess.stderr);
    /// </code>
    /// <br /><br />
    /// The <c>subprocess.stdio</c> property can be <c>undefined</c> if the child process could
    /// not be successfully spawned.
    /// </summary>
    /// <remarks>@since v0.7.10</remarks>
    abstract stdio: Writable option * Readable option * Readable option * U2<Readable, Writable> option * U2<Readable, Writable> option
    /// <summary>
    /// The <c>subprocess.killed</c> property indicates whether the child process
    /// successfully received a signal from <c>subprocess.kill()</c>. The <c>killed</c> property
    /// does not indicate that the child process has been terminated.
    /// </summary>
    /// <remarks>@since v0.5.10</remarks>
    abstract killed: bool
    /// <summary>
    /// Returns the process identifier (PID) of the child process. If the child process
    /// fails to spawn due to errors, then the value is <c>undefined</c> and <c>error</c> is
    /// emitted.
    /// <code lang="js">
    /// import { spawn } from 'node:child_process';
    /// const grep = spawn('grep', ['ssh']);
    ///
    /// console.log(`Spawned child pid: ${grep.pid}`);
    /// grep.stdin.end();
    /// </code>
    /// </summary>
    /// <remarks>@since v0.1.90</remarks>
    abstract pid: float option
    /// <summary>
    /// The <c>subprocess.connected</c> property indicates whether it is still possible to
    /// send and receive messages from a child process. When <c>subprocess.connected</c> is <c>false</c>, it is no longer possible to send or receive messages.
    /// </summary>
    /// <remarks>@since v0.7.2</remarks>
    abstract connected: bool
    /// <summary>
    /// The <c>subprocess.exitCode</c> property indicates the exit code of the child process.
    /// If the child process is still running, the field will be <c>null</c>.
    /// </summary>
    abstract exitCode: float option
    /// <summary>
    /// The <c>subprocess.signalCode</c> property indicates the signal received by
    /// the child process if any, else <c>null</c>.
    /// </summary>
    abstract signalCode: ChildProcess.SignalCode option
    /// <summary>
    /// The <c>subprocess.spawnargs</c> property represents the full list of command-line
    /// arguments the child process was launched with.
    /// </summary>
    abstract spawnargs: string[]
    /// <summary>
    /// The <c>subprocess.spawnfile</c> property indicates the executable file name of
    /// the child process that is launched.
    /// <br /><br />
    /// For fork, its value will be equal to <c>process.execPath</c>.
    /// For spawn, its value will be the name of
    /// the executable file.
    /// For exec,  its value will be the name of the shell
    /// in which the child process is launched.
    /// </summary>
    abstract spawnfile: string
    /// <summary>
    /// The <c>subprocess.kill()</c> method sends a signal to the child process. If no
    /// argument is given, the process will be sent the <c>'SIGTERM'</c> signal. See <a href="http://man7.org/linux/man-pages/man7/signal.7.html"><c>signal(7)</c></a> for a list of available signals. This function
    /// returns <c>true</c> if <a href="http://man7.org/linux/man-pages/man2/kill.2.html"><c>kill(2)</c></a> succeeds, and <c>false</c> otherwise.
    /// <code lang="js">
    /// import { spawn } from 'node:child_process';
    /// const grep = spawn('grep', ['ssh']);
    ///
    /// grep.on('close', (code, signal) =&gt; {
    ///   console.log(
    ///     `child process terminated due to receipt of signal ${signal}`);
    /// });
    ///
    /// // Send SIGHUP to process.
    /// grep.kill('SIGHUP');
    /// </code>
    /// <br /><br />
    /// The <c>ChildProcess</c> object may emit an <c>'error'</c> event if the signal
    /// cannot be delivered. Sending a signal to a child process that has already exited
    /// is not an error but may have unforeseen consequences. Specifically, if the
    /// process identifier (PID) has been reassigned to another process, the signal will
    /// be delivered to that process instead which can have unexpected results.
    /// <br /><br />
    /// While the function is called <c>kill</c>, the signal delivered to the child process
    /// may not actually terminate the process.
    /// <br /><br />
    /// See <a href="http://man7.org/linux/man-pages/man2/kill.2.html"><c>kill(2)</c></a> for reference.
    /// <br /><br />
    /// On Windows, where POSIX signals do not exist, the <c>signal</c> argument will be
    /// ignored, and the process will be killed forcefully and abruptly (similar to <c>'SIGKILL'</c>).
    /// See <c>Signal Events</c> for more details.
    /// <br /><br />
    /// On Linux, child processes of child processes will not be terminated
    /// when attempting to kill their parent. This is likely to happen when running a
    /// new process in a shell or with the use of the <c>shell</c> option of <c>ChildProcess</c>:
    /// <code lang="js">
    /// 'use strict';
    /// import { spawn } from 'node:child_process';
    ///
    /// const subprocess = spawn(
    ///   'sh',
    ///   [
    ///     '-c',
    ///     `node -e "setInterval(() =&gt; {
    ///       console.log(process.pid, 'is alive')
    ///     }, 500);"`,
    ///   ], {
    ///     stdio: ['inherit', 'inherit', 'inherit'],
    ///   },
    /// );
    ///
    /// setTimeout(() =&gt; {
    ///   subprocess.kill(); // Does not terminate the Node.js process in the shell.
    /// }, 2000);
    /// </code>
    /// </summary>
    /// <remarks>@since v0.1.90</remarks>
    abstract kill: ?signal: U2<float, string> -> bool
    /// <summary>
    /// When an IPC channel has been established between the parent and child (
    /// i.e. when using fork), the <c>subprocess.send()</c> method can
    /// be used to send messages to the child process. When the child process is a
    /// Node.js instance, these messages can be received via the <c>'message'</c> event.
    /// <br /><br />
    /// The message goes through serialization and parsing. The resulting
    /// message might not be the same as what is originally sent.
    /// <br /><br />
    /// For example, in the parent script:
    /// <code lang="js">
    /// import cp from 'node:child_process';
    /// const n = cp.fork(`${__dirname}/sub.js`);
    ///
    /// n.on('message', (m) =&gt; {
    ///   console.log('PARENT got message:', m);
    /// });
    ///
    /// // Causes the child to print: CHILD got message: { hello: 'world' }
    /// n.send({ hello: 'world' });
    /// </code>
    /// <br /><br />
    /// And then the child script, <c>'sub.js'</c> might look like this:
    /// <code lang="js">
    /// process.on('message', (m) =&gt; {
    ///   console.log('CHILD got message:', m);
    /// });
    ///
    /// // Causes the parent to print: PARENT got message: { foo: 'bar', baz: null }
    /// process.send({ foo: 'bar', baz: NaN });
    /// </code>
    /// <br /><br />
    /// Child Node.js processes will have a <c>process.send()</c> method of their own
    /// that allows the child to send messages back to the parent.
    /// <br /><br />
    /// There is a special case when sending a <c>{cmd: 'NODE_foo'}</c> message. Messages
    /// containing a <c>NODE_</c> prefix in the <c>cmd</c> property are reserved for use within
    /// Node.js core and will not be emitted in the child's <c>'message'</c> event. Rather, such messages are emitted using the <c>'internalMessage'</c> event and are consumed internally by Node.js.
