    /// import { spawn } from 'node:child_process';
    ///
    /// const subprocess = spawn(process.argv[0], ['child_program.js'], {
    ///   detached: true,
    ///   stdio: 'ignore',
    /// });
    ///
    /// subprocess.unref();
    /// subprocess.ref();
    /// </code>
    /// </summary>
    /// <remarks>@since v0.7.10</remarks>
    abstract ref: unit -> unit
