module Worker =
    module AddListener =
        type Listener = delegate of code: float * signal: string -> unit

        type Listener2 = delegate of message: obj * handle: U2<Server3, Socket2> -> unit

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type Disconnect =
        | [<CompiledName("disconnect")>] Disconnect

    module On =
        type Listener = delegate of code: float * signal: string -> unit

        type Listener2 = delegate of message: obj * handle: U2<Server3, Socket2> -> unit

    module Once =
        type Listener = delegate of code: float * signal: string -> unit

        type Listener2 = delegate of message: obj * handle: U2<Server3, Socket2> -> unit

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type Online =
        | [<CompiledName("online")>] Online

    module PrependListener =
        type Listener = delegate of code: float * signal: string -> unit

        type Listener2 = delegate of message: obj * handle: U2<Server3, Socket2> -> unit

    module PrependOnceListener =
        type Listener = delegate of code: float * signal: string -> unit

        type Listener2 = delegate of message: obj * handle: U2<Server3, Socket2> -> unit

type Cluster =
    inherit EventEmitter<unit[]>
    abstract disconnect: ?callback: (unit -> unit) -> unit
