    /// </summary>
    /// <remarks>@since v0.7.0</remarks>
    abstract workers: Record<string, Worker option> option
    abstract SCHED_NONE: float
    abstract SCHED_RR: float
    /// <summary>
    /// events.EventEmitter
    ///   1. disconnect
    ///   2. exit
    ///   3. fork
    ///   4. listening
    ///   5. message
    ///   6. online
    ///   7. setup
