    /// <param name="eventName">The name of the event being listened for</param>
    /// <param name="listener">The event handler function</param>
    abstract listenerCount: eventName: obj * ?listener: JS.Function -> float

module Cluster =
    module AddListener =
        type Listener = delegate of worker: Worker * code: float * signal: string -> unit

        type Listener2 = delegate of worker: Worker * address: Address -> unit

        type Listener3 = delegate of worker: Worker * message: obj * handle: U2<Server3, Socket2> -> unit

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type Disconnect =
        | [<CompiledName("disconnect")>] Disconnect

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type Fork =
        | [<CompiledName("fork")>] Fork

    module On =
        type Listener = delegate of worker: Worker * code: float * signal: string -> unit

        type Listener2 = delegate of worker: Worker * address: Address -> unit

        type Listener3 = delegate of worker: Worker * message: obj * handle: U2<Server3, Socket2> -> unit

    module Once =
        type Listener = delegate of worker: Worker * code: float * signal: string -> unit

        type Listener2 = delegate of worker: Worker * address: Address -> unit

        type Listener3 = delegate of worker: Worker * message: obj * handle: U2<Server3, Socket2> -> unit

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type Online =
        | [<CompiledName("online")>] Online

    module PrependListener =
        type Listener = delegate of worker: Worker * code: float * signal: string -> unit

        type Listener2 = delegate of worker: Worker * address: Address -> unit

        type Listener3 = delegate of worker: Worker * message: obj * handle: U2<Server3, Socket2> -> unit

    module PrependOnceListener =
        type Listener = delegate of worker: Worker * code: float * signal: string -> unit

        type Listener2 = delegate of worker: Worker * address: Address -> unit

        type Listener3 = delegate of worker: Worker * message: obj * handle: U2<Server3, Socket2> -> unit

