    interface end

type AsyncDisposable =
    interface end

[<Interface>]
type RelativeIndexable<'T> =
    abstract at: index: float -> 'T option
    [<ParamObject; Emit("$0")>]
    static member Create (at: (float -> 'T option)) : RelativeIndexable<'T> = jsNative

[<Interface>]
type Console =
    abstract Console: ConsoleConstructor with get, set
    /// <summary>
    /// <c>console.assert()</c> writes a message if <c>value</c> is <a href="https://developer.mozilla.org/en-US/docs/Glossary/Falsy">falsy</a> or omitted. It only
    /// writes a message and does not otherwise affect execution. The output always
    /// starts with <c>"Assertion failed"</c>. If provided, <c>message</c> is formatted using
    /// <a href="https://nodejs.org/docs/latest-v22.x/api/util.html#utilformatformat-args"><c>util.format()</c></a>.
    /// <br /><br />
    /// If <c>value</c> is <a href="https://developer.mozilla.org/en-US/docs/Glossary/Truthy">truthy</a>, nothing happens.
    /// <code lang="js">
    /// console.assert(true, 'does nothing');
    ///
    /// console.assert(false, 'Whoops %s work', 'didn\'t');
    /// // Assertion failed: Whoops didn't work
    ///
    /// console.assert();
    /// // Assertion failed
    /// </code>
    /// </summary>
    /// <remarks>@since v0.1.101</remarks>
    /// <param name="value">The value tested for being truthy.</param>
    /// <param name="message">All arguments besides <c>value</c> are used as error message.</param>
    abstract ``assert``: value: obj * message: string option * [<ParamArray>] optionalParams: obj[] -> unit
    /// <summary>
    /// When <c>stdout</c> is a TTY, calling <c>console.clear()</c> will attempt to clear the
    /// TTY. When <c>stdout</c> is not a TTY, this method does nothing.
    /// <br /><br />
    /// The specific operation of <c>console.clear()</c> can vary across operating systems
    /// and terminal types. For most Linux operating systems, <c>console.clear()</c> operates similarly to the <c>clear</c> shell command. On Windows, <c>console.clear()</c> will clear only the output in the
    /// current terminal viewport for the Node.js
    /// binary.
    /// </summary>
    /// <remarks>@since v8.3.0</remarks>
    abstract clear: unit -> unit
    /// <summary>
    /// Maintains an internal counter specific to <c>label</c> and outputs to <c>stdout</c> the
    /// number of times <c>console.count()</c> has been called with the given <c>label</c>.
    /// <code lang="js">
    /// &gt; console.count()
    /// default: 1
    /// undefined
    /// &gt; console.count('default')
    /// default: 2
    /// undefined
    /// &gt; console.count('abc')
    /// abc: 1
    /// undefined
    /// &gt; console.count('xyz')
    /// xyz: 1
    /// undefined
    /// &gt; console.count('abc')
    /// abc: 2
    /// undefined
    /// &gt; console.count()
    /// default: 3
    /// undefined
    /// &gt;
    /// </code>
    /// </summary>
    /// <remarks>@since v8.3.0</remarks>
    /// <param name="label">The display label for the counter.</param>
    abstract count: ?label: string -> unit
    /// <summary>
    /// Resets the internal counter specific to <c>label</c>.
    /// <code lang="js">
    /// &gt; console.count('abc');
    /// abc: 1
    /// undefined
    /// &gt; console.countReset('abc');
    /// undefined
    /// &gt; console.count('abc');
    /// abc: 1
    /// undefined
    /// &gt;
    /// </code>
    /// </summary>
    /// <remarks>@since v8.3.0</remarks>
    /// <param name="label">The display label for the counter.</param>
    abstract countReset: ?label: string -> unit
    /// <summary>
    /// The <c>console.debug()</c> function is an alias for log.
    /// </summary>
    /// <remarks>@since v8.0.0</remarks>
    abstract debug: message: obj option * [<ParamArray>] optionalParams: obj[] -> unit
    /// <summary>
    /// Uses <a href="https://nodejs.org/docs/latest-v22.x/api/util.html#utilinspectobject-options"><c>util.inspect()</c></a> on <c>obj</c> and prints the resulting string to <c>stdout</c>.
    /// This function bypasses any custom <c>inspect()</c> function defined on <c>obj</c>.
    /// </summary>
    /// <remarks>@since v0.1.101</remarks>
    abstract dir: obj: obj * ?options: InspectOptions -> unit
    /// <summary>
    /// This method calls <c>console.log()</c> passing it the arguments received.
    /// This method does not produce any XML formatting.
    /// </summary>
    /// <remarks>@since v8.0.0</remarks>
    abstract dirxml: [<ParamArray>] data: obj[] -> unit
    /// <summary>
    /// Prints to <c>stderr</c> with newline. Multiple arguments can be passed, with the
    /// first used as the primary message and all additional used as substitution
    /// values similar to <a href="http://man7.org/linux/man-pages/man3/printf.3.html"><c>printf(3)</c></a>
    /// (the arguments are all passed to <a href="https://nodejs.org/docs/latest-v22.x/api/util.html#utilformatformat-args"><c>util.format()</c></a>).
    /// <code lang="js">
    /// const code = 5;
    /// console.error('error #%d', code);
    /// // Prints: error #5, to stderr
    /// console.error('error', code);
    /// // Prints: error 5, to stderr
    /// </code>
    /// <br /><br />
    /// If formatting elements (e.g. <c>%d</c>) are not found in the first string then
    /// <a href="https://nodejs.org/docs/latest-v22.x/api/util.html#utilinspectobject-options"><c>util.inspect()</c></a> is called on each argument and the
    /// resulting string values are concatenated. See <a href="https://nodejs.org/docs/latest-v22.x/api/util.html#utilformatformat-args"><c>util.format()</c></a>
    /// for more information.
    /// </summary>
    /// <remarks>@since v0.1.100</remarks>
    abstract error: message: obj option * [<ParamArray>] optionalParams: obj[] -> unit
    /// <summary>
    /// Increases indentation of subsequent lines by spaces for <c>groupIndentation</c> length.
    /// <br /><br />
    /// If one or more <c>label</c>s are provided, those are printed first without the
    /// additional indentation.
    /// </summary>
    /// <remarks>@since v8.5.0</remarks>
    abstract group: [<ParamArray>] label: obj[] -> unit
    /// <summary>
    /// An alias for group.
