    /// its <c>hash.digest()</c> method has been called.
    /// <code lang="js">
    /// // Calculate a rolling hash.
    /// const {
    ///   createHash,
    /// } = await import('node:crypto');
    ///
    /// const hash = createHash('sha256');
    ///
    /// hash.update('one');
    /// console.log(hash.copy().digest('hex'));
    ///
    /// hash.update('two');
    /// console.log(hash.copy().digest('hex'));
    ///
    /// hash.update('three');
    /// console.log(hash.copy().digest('hex'));
