    /// process.nextTick(() =&gt; {
    ///   ee.emit('myevent', 42);
    /// });
    ///
    /// const [value] = await once(ee, 'myevent');
    /// console.log(value);
    ///
    /// const err = new Error('kaboom');
    /// process.nextTick(() =&gt; {
    ///   ee.emit('error', err);
    /// });
    ///
    /// try {
    ///   await once(ee, 'myevent');
    /// } catch (err) {
