type ReadableConstructor =
    /// <summary>
    /// Creates a <c>Promise</c> that is fulfilled when the <c>EventEmitter</c> emits the given
    /// event or that is rejected if the <c>EventEmitter</c> emits <c>'error'</c> while waiting.
    /// The <c>Promise</c> will resolve with an array of all the arguments emitted to the
    /// given event.
    /// <br /><br />
    /// This method is intentionally generic and works with the web platform <a href="https://dom.spec.whatwg.org/#interface-eventtarget">EventTarget</a> interface, which has no special<c>'error'</c> event
    /// semantics and does not listen to the <c>'error'</c> event.
    /// <code lang="js">
    /// import { once, EventEmitter } from 'node:events';
    /// import process from 'node:process';
    ///
    /// const ee = new EventEmitter();
    ///
    /// process.nextTick(() =&gt; {
    ///   ee.emit('myevent', 42);
    /// });
    ///
    /// const [value] = await once(ee, 'myevent');
    /// console.log(value);
    ///
    /// const err = new Error('kaboom');
    /// process.nextTick(() =&gt; {
    ///   ee.emit('error', err);
    /// });
    ///
    /// try {
    ///   await once(ee, 'myevent');
    /// } catch (err) {
    ///   console.error('error happened', err);
    /// }
    /// </code>
    /// <br /><br />
    /// The special handling of the <c>'error'</c> event is only used when <c>events.once()</c> is used to wait for another event. If <c>events.once()</c> is used to wait for the
    /// '<c>error'</c> event itself, then it is treated as any other kind of event without
    /// special handling:
    /// <code lang="js">
    /// import { EventEmitter, once } from 'node:events';
    ///
    /// const ee = new EventEmitter();
    ///
    /// once(ee, 'error')
    ///   .then(([err]) =&gt; console.log('ok', err.message))
    ///   .catch((err) =&gt; console.error('error', err.message));
    ///
    /// ee.emit('error', new Error('boom'));
    ///
    /// // Prints: ok boom
    /// </code>
    /// <br /><br />
    /// An <c>AbortSignal</c> can be used to cancel waiting for the event:
    /// <code lang="js">
    /// import { EventEmitter, once } from 'node:events';
    ///
    /// const ee = new EventEmitter();
    /// const ac = new AbortController();
    ///
    /// async function foo(emitter, event, signal) {
    ///   try {
    ///     await once(emitter, event, { signal });
    ///     console.log('event emitted!');
    ///   } catch (error) {
    ///     if (error.name === 'AbortError') {
    ///       console.error('Waiting for the event was canceled!');
    ///     } else {
    ///       console.error('There was an error', error.message);
    ///     }
    ///   }
    /// }
    ///
    /// foo(ee, 'foo', ac.signal);
    /// ac.abort(); // Abort waiting for the event
    /// ee.emit('foo'); // Prints: Waiting for the event was canceled!
    /// </code>
    /// </summary>
    /// <remarks>@since v11.13.0, v10.16.0</remarks>
    abstract once: emitter: EventEmitter2<unit[]> * eventName: obj * ?options: StaticEventEmitterOptions -> JS.Promise<obj[]>
    /// <summary>
