    /// function pong() {
    ///   console.log('pong');
    /// }
    ///
    /// ee.on('ping', pong);
    /// ee.once('ping', pong);
    /// ee.removeListener('ping', pong);
    ///
    /// ee.emit('ping');
    /// ee.emit('ping');
    /// </code>
    /// <br /><br />
    /// Returns a reference to the <c>EventEmitter</c>, so that calls can be chained.
    /// </summary>
    abstract removeListener: ``event``: string * listener: (unit -> unit) -> DecipherOCB
