        and set (_: (U4<Readable, ReadableStream3, Writable, WritableStream3> -> bool)): unit = jsNative
    /// <summary>
    /// Returns whether the stream is readable.
    /// </summary>
    /// <remarks>@since v17.4.0, v16.14.0</remarks>
    /// <returns>Only returns <c>null</c> if <c>stream</c> is not a valid <c>Readable</c>, <c>Duplex</c> or <c>ReadableStream</c>.</returns>
    static member isReadable
        with get (): (U2<Readable, ReadableStream3> -> bool option) = jsNative
        and set (_: (U2<Readable, ReadableStream3> -> bool option)): unit = jsNative
    /// <summary>
    /// Returns whether the stream is writable.
    /// </summary>
    /// <remarks>@since v20.0.0</remarks>
    /// <returns>Only returns <c>null</c> if <c>stream</c> is not a valid <c>Writable</c>, <c>Duplex</c> or <c>WritableStream</c>.</returns>
    static member isWritable
        with get (): (U2<Writable, WritableStream3> -> bool option) = jsNative
        and set (_: (U2<Writable, WritableStream3> -> bool option)): unit = jsNative

