    /// <code lang="js">
    /// import { EventEmitter } from 'node:events';
    /// const ee = new EventEmitter();
    ///
    /// function pong() {
    ///   console.log('pong');
    /// }
    ///
    /// ee.on('ping', pong);
    /// ee.once('ping', pong);
    /// ee.removeListener('ping', pong);
    ///
    /// ee.emit('ping');
    /// ee.emit('ping');
    /// </code>
