    /// <code lang="js">
    /// import http2 from 'node:http2';
    /// const options = getSecureOptionsSomehow();
    /// options.origins = ['https://example.com', 'https://example.org'];
    /// const server = http2.createSecureServer(options);
    /// server.on('stream', (stream) =&gt; {
    ///   stream.respond();
    ///   stream.end('ok');
    /// });
    /// </code>
    /// </summary>
    /// <remarks>@since v10.12.0</remarks>
    /// <param name="origins">One or more URL Strings passed as separate arguments.</param>
    abstract origin: [<ParamArray>] origins: U3<string, URL, ServerHttp2Session.Origin.Origins.Item>[] -> unit
    /// <summary>
    /// Alias for <c>emitter.on(eventName, listener)</c>.
    /// </summary>
    abstract addListener: ``event``: string * listener: ServerHttp2Session.AddListener.Listener -> ServerHttp2Session<'Http1Request, 'Http1Response, 'Http2Request, 'Http2Response>
    /// <summary>
