    ///   href: 'http://example.com/status?name=ryan',
    ///   origin: 'http://example.com',
    ///   protocol: 'http:',
    ///   username: '',
    ///   password: '',
    ///   host: 'example.com',
    ///   hostname: 'example.com',
    ///   port: '',
    ///   pathname: '/status',
    ///   search: '?name=ryan',
    ///   searchParams: URLSearchParams { 'name' =&gt; 'ryan' },
