        and set (_: (U4<Readable, ReadableStream3, Writable, WritableStream3> -> bool)): unit = jsNative

module Http2ServerRequest =
    module AddListener =
        type Listener = delegate of hadError: bool * code: float -> unit

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type Close =
        | [<CompiledName("close")>] Close

    module Compose =
        [<Interface>]
        type Options =
            abstract signal: AbortSignal with get, set
            [<ParamObject; Emit("$0")>]
            static member Create (signal: AbortSignal) : Options = jsNative

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type End =
        | [<CompiledName("end")>] End

    module On =
        type Listener = delegate of hadError: bool * code: float -> unit

    module Once =
        type Listener = delegate of hadError: bool * code: float -> unit

    module Pipe =
        [<Interface>]
        type Options =
            abstract ``end``: bool option with get, set
            [<ParamObject; Emit("$0")>]
            static member Create (?``end``: bool) : Options = jsNative

    module PrependListener =
        type Listener = delegate of hadError: bool * code: float -> unit

    module PrependOnceListener =
        type Listener = delegate of hadError: bool * code: float -> unit

    [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
    type Readable =
        | [<CompiledName("readable")>] Readable

/// <summary>
/// This object is created internally by an HTTP server, not by the user. It is
/// passed as the second parameter to the <c>'request'</c> event.
/// </summary>
/// <remarks>@since v8.4.0</remarks>
[<Interface>]
[<Import("Http2ServerResponse", "http2")>]
type Http2ServerResponse<'Request when 'Request :> Http2ServerRequest> =
    inherit Writable
    /// <summary>
    /// See <c>response.socket</c>.
    /// </summary>
