    /// const server = http2.createServer((req, res) =&gt; {
    ///   res.setHeader('set-cookie', 'a');
    ///   res.appendHeader('set-cookie', 'b');
    ///   res.writeHead(200);
    ///   res.end('ok');
    /// });
