    abstract finished: bool
    /// <summary>
    /// True if headers were sent, false otherwise (read-only).
    /// </summary>
    /// <remarks>@since v8.4.0</remarks>
    abstract headersSent: bool
    /// <summary>
    /// A reference to the original HTTP2 <c>request</c> object.
    /// </summary>
