    /// The function to execute, optionally accepting a single string argument.
    /// </summary>
    abstract action: REPLCommandAction with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (action: REPLCommandAction, ?help: string) : REPLCommand = jsNative

/// <summary>
/// Instances of <c>repl.REPLServer</c> are created using the start method
/// or directly using the JavaScript <c>new</c> keyword.
/// <code lang="js">
/// import repl from 'node:repl';
///
/// const options = { useColors: true };
///
/// const firstInstance = repl.start(options);
/// const secondInstance = new repl.REPLServer(options);
/// </code>
/// </summary>
/// <remarks>@since v0.1.91</remarks>
[<Interface>]
[<Import("REPLServer", "node:repl")>]
type REPLServer =
