    /// <summary>
    /// The <c>vm.Context</c> provided to the <c>eval</c> function to be used for JavaScript
    /// evaluation.
    /// </summary>
    abstract context: Context
    /// <remarks>@deprecated since v14.3.0 - Use <c>input</c> instead.</remarks>
    abstract inputStream: ReadableStream3
    /// <remarks>@deprecated since v14.3.0 - Use <c>output</c> instead.</remarks>
    abstract outputStream: WritableStream3
    /// <summary>
    /// The <c>Readable</c> stream from which REPL input will be read.
    /// </summary>
    abstract input: ReadableStream3
    /// <summary>
    /// The <c>Writable</c> stream to which REPL output will be written.
    /// </summary>
    abstract output: WritableStream3
    /// <summary>
    /// The commands registered via <c>replServer.defineCommand()</c>.
    /// </summary>
