    abstract before: ?fn: TestContextHookFn * ?options: HookOptions -> unit
    /// <summary>
    /// This function is used to create a hook running before each subtest of the current test.
    /// </summary>
    /// <param name="fn">
    /// The hook function. The first argument to this function is a <c>TestContext</c> object.
    /// If the hook uses callbacks, the callback function is passed as the second argument.
    /// </param>
    /// <param name="options">Configuration options for the hook.</param>
    /// <remarks>@since v18.8.0</remarks>
    abstract beforeEach: ?fn: TestContextHookFn * ?options: HookOptions -> unit
    /// <summary>
    /// This function is used to create a hook that runs after the current test finishes.
    /// </summary>
    /// <param name="fn">
    /// The hook function. The first argument to this function is a <c>TestContext</c> object.
    /// If the hook uses callbacks, the callback function is passed as the second argument.
    /// </param>
    /// <param name="options">Configuration options for the hook.</param>
    /// <remarks>@since v18.13.0</remarks>
    abstract after: ?fn: TestContextHookFn * ?options: HookOptions -> unit
    /// <summary>
    /// This function is used to create a hook running after each subtest of the current test.
    /// </summary>
    /// <param name="fn">
    /// The hook function. The first argument to this function is a <c>TestContext</c> object.
    /// If the hook uses callbacks, the callback function is passed as the second argument.
    /// </param>
    /// <param name="options">Configuration options for the hook.</param>
    /// <remarks>@since v18.8.0</remarks>
    abstract afterEach: ?fn: TestContextHookFn * ?options: HookOptions -> unit
    /// <summary>
    /// This function is used to write diagnostics to the output. Any diagnostic
    /// information is included at the end of the test's results. This function does
    /// not return a value.
    /// <code lang="js">
    /// test('top level test', (t) =&gt; {
    ///   t.diagnostic('A diagnostic message');
    /// });
    /// </code>
    /// </summary>
    /// <remarks>@since v18.0.0, v16.17.0</remarks>
    /// <param name="message">Message to be reported.</param>
    abstract diagnostic: message: string -> unit
    /// <summary>
    /// The absolute path of the test file that created the current test. If a test file imports
    /// additional modules that generate tests, the imported tests will return the path of the root test file.
    /// </summary>
    /// <remarks>@since v22.6.0</remarks>
