    /// <returns>Fulfilled with the value returned by <c>condition</c>.</returns>
    abstract waitFor<'T>: condition: (unit -> 'T) * ?options: TestContextWaitForOptions -> JS.Promise<obj>
    /// <summary>
    /// Each test provides its own MockTracker instance.
    /// </summary>
    abstract mock: MockTracker
    [<ParamObject; Emit("$0")>]
    static member Create (``assert``: TestContextAssert, before: Action<TestContextHookFn option, HookOptions option>, beforeEach: Action<TestContextHookFn option, HookOptions option>, after: Action<TestContextHookFn option, HookOptions option>, afterEach: Action<TestContextHookFn option, HookOptions option>, diagnostic: (string -> unit), fullName: string, name: string, plan: Action<float, TestContextPlanOptions option>, runOnly: (bool -> unit), signal: AbortSignal, skip: (string option -> unit), todo: (string option -> unit), test: Test, waitFor: Func<(unit -> 'T), TestContextWaitForOptions option, JS.Promise<obj>>, mock: MockTracker, ?filePath: string) : TestContext = jsNative

type TestContextAssert =
    inherit Assert.Base
    /// <summary>
    /// This function serializes <c>value</c> and writes it to the file specified by <c>path</c>.
    /// <code lang="js">
    /// test('snapshot test with default serialization', (t) =&gt; {
    ///   t.assert.fileSnapshot({ value1: 1, value2: 2 }, './snapshots/snapshot.json');
    /// });
    /// </code>
    /// <br /><br />
    /// This function differs from <c>context.assert.snapshot()</c> in the following ways:
    /// <br /><br />
    /// * The snapshot file path is explicitly provided by the user.
    /// * Each snapshot file is limited to a single snapshot value.
    /// * No additional escaping is performed by the test runner.
    /// <br /><br />
