    /// hint to send to a client to help
    /// with selecting the identity during TLS-PSK negotiation. Will be ignored
    /// in TLS 1.3. Upon failing to set pskIdentityHint <c>tlsClientError</c> will be
    /// emitted with <c>ERR_TLS_PSK_SET_IDENTIY_HINT_FAILED</c> code.
    /// </summary>
    abstract pskIdentityHint: string option with get, set

[<Interface>]
type PSKCallbackNegotation =
    abstract psk: obj with get, set
    abstract identity: string with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (psk: obj, identity: string) : PSKCallbackNegotation = jsNative

type ConnectionOptions =
