    abstract workerData: obj option with get, set
    abstract stdin: bool option with get, set
    abstract stdout: bool option with get, set
    abstract stderr: bool option with get, set
    abstract execArgv: string[] option with get, set
    abstract resourceLimits: ResourceLimits option with get, set
