    static member Create (?argv: obj[], ?env: obj, ?eval: bool, ?workerData: obj, ?stdin: bool, ?stdout: bool, ?stderr: bool, ?execArgv: string[], ?resourceLimits: ResourceLimits, ?transferList: Transferable[], ?trackUnmanagedFds: bool, ?name: string) : WorkerOptions = jsNative

[<Interface>]
type ResourceLimits =
    /// <summary>
    /// The maximum size of a heap space for recently created objects.
    /// </summary>
