    /// <summary>
    /// The size of a pre-allocated memory range used for generated code.
    /// </summary>
    abstract codeRangeSizeMb: float option with get, set
    /// <summary>
    /// The default maximum stack size for the thread. Small values may lead to unusable Worker instances.
    /// </summary>
    /// <defaultValue>4</defaultValue>
    abstract stackSizeMb: float option with get, set
    [<ParamObject; Emit("$0")>]
    static member Create (?maxYoungGenerationSizeMb: float, ?maxOldGenerationSizeMb: float, ?codeRangeSizeMb: float, ?stackSizeMb: float) : ResourceLimits = jsNative

[<Interface>]
type CPUProfileHandle =
    abstract stop: unit -> JS.Promise<string>
