    /// import { once, EventEmitter } from 'node:events';
    /// import process from 'node:process';
    ///
    /// const ee = new EventEmitter();
    ///
    /// process.nextTick(() =&gt; {
    ///   ee.emit('myevent', 42);
    /// });
    ///
    /// const [value] = await once(ee, 'myevent');
    /// console.log(value);
    ///
    /// const err = new Error('kaboom');
    /// process.nextTick(() =&gt; {
    ///   ee.emit('error', err);
    /// });
    ///
    /// try {
    ///   await once(ee, 'myevent');
    /// } catch (err) {
    ///   console.error('error happened', err);
    /// }
    /// </code>
    /// <br /><br />
    /// The special handling of the <c>'error'</c> event is only used when <c>events.once()</c> is used to wait for another event. If <c>events.once()</c> is used to wait for the
    /// '<c>error'</c> event itself, then it is treated as any other kind of event without
    /// special handling:
    /// <code lang="js">
    /// import { EventEmitter, once } from 'node:events';
    ///
    /// const ee = new EventEmitter();
    ///
    /// once(ee, 'error')
    ///   .then(([err]) =&gt; console.log('ok', err.message))
    ///   .catch((err) =&gt; console.error('error', err.message));
    ///
    /// ee.emit('error', new Error('boom'));
    ///
    /// // Prints: ok boom
    /// </code>
    /// <br /><br />
    /// An <c>AbortSignal</c> can be used to cancel waiting for the event:
    /// <code lang="js">
    /// import { EventEmitter, once } from 'node:events';
    ///
    /// const ee = new EventEmitter();
    /// const ac = new AbortController();
    ///
    /// async function foo(emitter, event, signal) {
    ///   try {
    ///     await once(emitter, event, { signal });
    ///     console.log('event emitted!');
    ///   } catch (error) {
    ///     if (error.name === 'AbortError') {
