    /// <code lang="js">
    /// import {
    ///   createReadStream,
    ///   createWriteStream,
    /// } from 'node:fs';
    ///
    /// import {
    ///   pipeline,
    /// } from 'node:stream';
    ///
    /// const {
    ///   scrypt,
    ///   randomFill,
    ///   createCipheriv,
    /// } = await import('node:crypto');
    ///
    /// const algorithm = 'aes-192-cbc';
