    /// mkdtemp(`${tmpDir}${sep}`, (err, directory) =&gt; {
    ///   if (err) throw err;
    ///   console.log(directory);
    ///   // Will print something similar to `/tmp/abc123`.
    ///   // A new temporary directory is created within
    ///   // the /tmp directory.
    /// });
    /// </code>
